import Accordion from "@mui/material/Accordion";
import AccordionSummary from "@mui/material/AccordionSummary";
import AccordionDetails from "@mui/material/AccordionDetails";
import Typography from "@mui/material/Typography";
import ExpandMoreIcon from "@mui/icons-material/ExpandMore";
import Section from "./Section";
import Box from "@mui/material/Box";

const servicess = [
  {
    title: "Генеральне прибирання:",
    details: [
      "глибока чистка поверхонь",
      "видалення застарілих забруднень",
      "миття стелі, стін, скла, всіх інших поверхонь",
    ],
  },
  {
    title: "Підтримуюче прибирання:",
    details: [
      "видалення забруднень, які виникають в процесі щоденного користування будівлі",
      "не стосується важкодоступних місць та відмивання складних зафіксованих забруднень",
    ],
  },
  {
    title: "Після квартирантів / перед заселенням:",
    details: [
      "повне миття поверхонь",
      "видалення запахів",
      "дезінфекція сантехніки",
      "обробка кухні від жиру",
      "прибирання під меблями",
    ],
  },
  {
    title: "Прибирання після ремонту",
    details: [
      "видалення будівельного пилу з усіх поверхонь",
      "миття вікон, рам, підвіконь від штукатурки, фарби",
      "очищення плитки, підлоги від клею, цементу",
      "протирка стін, меблів, освітлення",
      "полірування поверхонь",
      "вологе прибирання",
    ],
  },
];

const questions = [
  {
    title: "💸 Скільки це буде коштувати і від чого залежить ціна?",
    answer:
      "Вартість залежить від площі, стану приміщення та виду прибирання — стандартне, генеральне або після ремонту. Ми завжди формуємо чесну ціну після короткого уточнення деталей. Ви можете дізнатися орієнтовну вартість через форму онлайн-заявки або по телефону.",
  },
  {
    title: "🧹 Що саме входить у прибирання?",
    answer: (
      servicess.map(service => (
<Typography component="p" sx={{mb:3}}>
        <Typography>{service.title}</Typography>
                      <ul style={{ margin: 0, textAlign: "left" }}>
                {service.details.map((detail) => (
                  <li>
                    <span>{detail}</span>
                  </li>
                ))}
              </ul>
      </Typography>
      ))
      

    ),
  },
  {
    title: "⌛ Скільки часу займає прибирання?",
    answer:
      "Залежить від масштабу катастрофи 😅",
  },
  {
    title: "🚪 Чи потрібно щось готувати перед нашим приїздом?",
    answer:
      (<span>Так. <br/><b>Гроші</b> 🤭</span>),
  },
];

export default function FAQ() {

  return (
    <Section id="faq" title="Нас часто запитують">
      <Box pb={3}>
        {questions.map((question) => (
          <Accordion key={question.title}>
            <AccordionSummary
              expandIcon={<ExpandMoreIcon />}
              aria-controls="panel1-content"
              id="panel1-header"
            >
              <Typography component="span" sx={{ fontWeight: "700" }}>
                {question.title}
              </Typography>
            </AccordionSummary>
            <AccordionDetails sx={{ textAlign: "left" }}>
              {question.answer}
            </AccordionDetails>
          </Accordion>
        ))}
      </Box>
    </Section>
  );
}
