import { Box, Container, Grid } from "@mui/material";
import Toolbar from "@mui/material/Toolbar";
import Typography from "@mui/material/Typography";
import Section from "./Section";
import Tab from "@mui/material/Tab";
import Tabs from "@mui/material/Tabs";
import * as React from "react";
import { useParams, useNavigate } from "react-router-dom";
import { useLocation } from "react-router-dom";

import AfterRepairImage from "../assets/after-repair.jpg";
import AfterRentImage from "../assets/after-rent-2.jpg";
import ForBusinessImage from "../assets/for-business-2.jpg";
import { ReactComponent as HourglassSvg } from "../assets/hourglass.svg";
import { ReactComponent as LogoSvg } from "../assets/logo.svg";
import { ReactComponent as SparkSvg } from "../assets/spark.svg";
